// src/components/FilmGallery.jsx
import React, { useState, useEffect, useMemo } from 'react';
import FilmCard from './FilmCard';

const formatTime = (totalMinutes) => {
    if (isNaN(totalMinutes) || totalMinutes < 0) return '0h 0m';
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    return `${hours}h ${minutes}m`;
};

function FilmGallery() {
    const [films, setFilms] = useState([]); // Дані, завантажені з сервера
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [totalTime, setTotalTime] = useState('0h 0m'); 
    
    // Стан для сортування
    const [sortBy, setSortBy] = useState('time-desc'); // Початкове значення: Довжина, спадання

    // --- ЛОГІКА ЗАВАНТАЖЕННЯ ДАНИХ ---
    useEffect(() => {
        fetch('/films') 
            .then(response => {
                // ... (частина з перевіркою response.ok)
                return response.json();
            })
            .then(data => {
                setFilms(data);
                setLoading(false);
            })
            .catch(err => {
                // ... (частина з обробкою помилок)
                setError("Could not load films from the server. Check if the server is running on port 5000.");
                setLoading(false);
                console.error("Fetch error: ", err);
            });
    }, []);
    // ------------------------------------
    
    // --- НОВА ЛОГІКА: СОРТУВАННЯ ---
    const displayedFilms = useMemo(() => {
        if (!films || films.length === 0) return [];

        // Створюємо копію, щоб не змінювати вихідний стан films
        const sortableFilms = [...films];

        sortableFilms.sort((a, b) => {
            if (sortBy === 'time-desc') {
                // Сортування за часом: від більшого до меншого
                return b.time - a.time; 
            }
            if (sortBy === 'time-asc') {
                // Сортування за часом: від меншого до більшого
                return a.time - b.time; 
            }
            if (sortBy === 'name-asc') {
                // Сортування за назвою (Name): А -> Я
                return a.name.localeCompare(b.name); 
            }
            // Додайте інші критерії сортування (наприклад, за рейтингом)
            return 0;
        });

        return sortableFilms;
    }, [films, sortBy]); // Перераховуємо, коли змінюються вихідні фільми або критерій сортування

    // --- ЛОГІКА Підрахунку загального часу ---
    const handleCountTotalTime = () => {
        const totalMinutes = films.reduce((sum, film) => sum + (film.time || 0), 0);
        setTotalTime(formatTime(totalMinutes));
    };
    // ----------------------------------------

    if (loading) {
        return <h2>Loading films...</h2>;
    }

    if (error) {
        return <h2 style={{ color: 'red' }}>Error: {error}</h2>;
    }

    return (
        <div className="film-list-container">
            {/* --- БЛОК УПРАВЛІННЯ (Manage films) --- */}
            <div className="manage-films-box">
                <h3>Manage films</h3>
                <div className="controls">
                    {/* Сортування */}
                    <label htmlFor="sortBy">Sort by:</label>
                    <select 
                        id="sortBy" 
                        value={sortBy} 
                        onChange={(e) => setSortBy(e.target.value)}
                        className="sort-select"
                    >
                        <option value="time-desc">Length (Descending)</option> 
                        <option value="time-asc">Length (Ascending)</option> 
                        <option value="name-asc">Name (A-Z)</option>
                    </select>
                </div>
                
                {/* Підрахунок часу */}
                <button 
                    onClick={handleCountTotalTime} 
                    className="count-time-button"
                >
                    Count total time
                </button>
                <p>Total Time: **{totalTime}**</p>
            </div>
            {/* ------------------------------------------- */}

            {/* --- ВІДОБРАЖЕННЯ СПИСКУ ФІЛЬМІВ --- */}
            <h3>Films Library ({displayedFilms.length} items)</h3>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
                {displayedFilms.map(film => (
                    // ТЕПЕР МИ ВИКОРИСТОВУЄМО displayedFilms
                    <FilmCard key={film.id} film={film} />
                ))}
            </div>
            {/* ------------------------------------- */}
        </div>
    );
}

export default FilmGallery;
